const payload = $input.item.json.body || {};
const lojaId = payload.loja_id ? parseInt(payload.loja_id, 10) : null;
const dias = payload.dias ? parseInt(payload.dias, 10) : 30;

return {
  json: {
    lojaId,
    dias
  }
};

const first = $input.first()?.json || {};
const data = first.data || {};

return {
  json: {
    ok: true,
    resumo: data.resumo || {},
    por_criativo: data.por_criativo || [],
    por_loja: data.por_loja || [],
    por_periodo: data.por_periodo || [],
    por_pessoa: data.por_pessoa || []
  }
};
